//! Sign an `ssdf.audit` chain-head checkpoint.
//!
//! Reads one JSON [`mecmcp_audit::checkpoint::Checkpoint`] object from stdin
//! (fields: `tier`, `server_id`, `row_count`, `head_row_hash`,
//! `checkpoint_ts`), signs it with the Ed25519 key at `<private-key-path>`
//! (generated by `mecmcp-audit-keygen`, and subject to the same fail-closed
//! 0600 permission check), and writes the checkpoint plus its signature and
//! signer `key_id` as one JSON object to stdout.
//!
//! The orchestrator (ssdf's `checkpoint_audit.py`) owns querying ClickHouse
//! for the chain head and inserting the signed result into
//! `ssdf.audit_checkpoints`; this binary's only job is the deterministic,
//! model-free signing step, kept in the crate that owns the audit-signing
//! key format and RFC 8032 known-answer coverage (`mecmcp-audit::signing`).
//!
//! Exit codes: 0 on success, 1 on bad input or key-file errors (fail closed —
//! never emits a partially-signed or unsigned checkpoint on stdout).

use mecmcp_audit::checkpoint::{Checkpoint, key_id, sign_checkpoint};
use mecmcp_audit::signing::{encode_signature, load_signing_key};
use std::io::Read;
use std::path::PathBuf;

fn usage(program: &str) -> String {
    format!(
        "Usage: {program} <private-key-path>\n\
         \n\
         Signs an ssdf.audit chain-head checkpoint.\n\
         Reads a JSON checkpoint object from stdin:\n\
         \x20 {{\"tier\":\"evidence\",\"server_id\":\"rustsdcmcp-606\",\n\
         \x20  \"row_count\":42,\"head_row_hash\":\"<hex>\",\n\
         \x20  \"checkpoint_ts\":\"2026-09-28T00:00:00.000Z\"}}\n\
         Writes the same object plus \"signature\" (base64) and \"key_id\"\n\
         (signer fingerprint) as JSON to stdout."
    )
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    if args.len() != 2 || args[1] == "-h" || args[1] == "--help" {
        eprintln!("{}", usage(&args[0]));
        std::process::exit(if args.len() != 2 { 1 } else { 0 });
    }

    let key_path = PathBuf::from(&args[1]);
    let signing_key = load_signing_key(&key_path).unwrap_or_else(|e| {
        eprintln!("Failed to load signing key: {e}");
        std::process::exit(1);
    });

    let mut input = String::new();
    std::io::stdin()
        .read_to_string(&mut input)
        .unwrap_or_else(|e| {
            eprintln!("Failed to read checkpoint JSON from stdin: {e}");
            std::process::exit(1);
        });

    let checkpoint: Checkpoint = serde_json::from_str(&input).unwrap_or_else(|e| {
        eprintln!("Invalid checkpoint JSON: {e}");
        std::process::exit(1);
    });

    let signature = sign_checkpoint(&checkpoint, &signing_key).unwrap_or_else(|e| {
        eprintln!("Failed to sign checkpoint: {e}");
        std::process::exit(1);
    });
    let signer_key_id = key_id(&signing_key.verifying_key());

    let output = serde_json::json!({
        "tier": checkpoint.tier,
        "server_id": checkpoint.server_id,
        "row_count": checkpoint.row_count,
        "head_row_hash": checkpoint.head_row_hash,
        "checkpoint_ts": checkpoint.checkpoint_ts,
        "signature": encode_signature(&signature),
        "key_id": signer_key_id,
    });

    println!("{output}");
}
